// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait Mining_Eligibility_supervisor_process_mining_eligibility_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_mining_eligibility)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_mining_eligibility)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_mining_eligibility)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_mining_eligibility)
  }

  /** helper function to set the values of all input ports.
   * @param intent payload for data port intent
   * @param threat_disposition payload for data port threat_disposition
   * @param assessment payload for data port assessment
   * @param recovery_gate payload for data port recovery_gate
   */
  def put_concrete_inputs(intent : Mining_Threat_Retreat_Supervision.IntentValue,
                          threat_disposition : Mining_Threat_Retreat_Supervision.ThreatDispositionValue,
                          assessment : Mining_Threat_Retreat_Supervision.ReadinessAssessmentValue,
                          recovery_gate : Mining_Threat_Retreat_Supervision.RecoveryGateValue): Unit = {
    put_intent(intent)
    put_threat_disposition(threat_disposition)
    put_assessment(assessment)
    put_recovery_gate(recovery_gate)
  }


  /** helper function to check Mining_Eligibility_supervisor_process_mining_eligibility's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param mining_proposal method that will be called with the value of the outgoing data
   *        port 'mining_proposal'.
   */
  def check_concrete_output(mining_proposal: Mining_Threat_Retreat_Supervision.ProposalValue => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val mining_proposalValue: Mining_Threat_Retreat_Supervision.ProposalValue = get_mining_proposal().get
    if(!mining_proposal(mining_proposalValue)) {
      testFailures = testFailures :+ st"'mining_proposal' did not match expected: value of the outgoing data port is ${mining_proposalValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_intent(value : Mining_Threat_Retreat_Supervision.IntentValue): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_mining_eligibility.operational_api.intent_Id, Mining_Threat_Retreat_Supervision.IntentValue_Payload(value))
  }

  // setter for in DataPort
  def put_threat_disposition(value : Mining_Threat_Retreat_Supervision.ThreatDispositionValue): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_mining_eligibility.operational_api.threat_disposition_Id, Mining_Threat_Retreat_Supervision.ThreatDispositionValue_Payload(value))
  }

  // setter for in DataPort
  def put_assessment(value : Mining_Threat_Retreat_Supervision.ReadinessAssessmentValue): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_mining_eligibility.operational_api.assessment_Id, Mining_Threat_Retreat_Supervision.ReadinessAssessmentValue_Payload(value))
  }

  // setter for in DataPort
  def put_recovery_gate(value : Mining_Threat_Retreat_Supervision.RecoveryGateValue): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_mining_eligibility.operational_api.recovery_gate_Id, Mining_Threat_Retreat_Supervision.RecoveryGateValue_Payload(value))
  }

  // getter for out DataPort
  def get_mining_proposal(): Option[Mining_Threat_Retreat_Supervision.ProposalValue] = {
    val value: Option[Mining_Threat_Retreat_Supervision.ProposalValue] = get_mining_proposal_payload() match {
      case Some(Mining_Threat_Retreat_Supervision.ProposalValue_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port mining_proposal.  Expecting 'Mining_Threat_Retreat_Supervision.ProposalValue_Payload' but received ${v}")
      case _ => None[Mining_Threat_Retreat_Supervision.ProposalValue]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_mining_proposal_payload(): Option[Mining_Threat_Retreat_Supervision.ProposalValue_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_mining_eligibility.initialization_api.mining_proposal_Id).asInstanceOf[Option[Mining_Threat_Retreat_Supervision.ProposalValue_Payload]]
  }

}
